 foreach(['club'=>['name'=>'Synthetic Association','street'=>'Testweg 1','postcode'=>'12345','city'=>'Musterstadt','phone'=>'+49 123 456789','email'=>'seller@example.org','register'=>'VR 12345 Musterstadt'],'tax'=>['number'=>'123/456/78901'],'bank'=>['iban'=>'DE89370400440532013000','holder'=>'Synthetic Association','account_id'=>$bank]] as $section=>$fields)$db->prepare('INSERT INTO club_settings(club_id,section,version,payload,updated_at) VALUES(?,?,1,?,?)')->execute(['a',$section,json_encode(array_replace(SettingsSchema::defaults($section),$fields)),gmdate('c')]);
 $s=new OutgoingInvoices($db,'admin');$data=['domestic_confirmed'=>'1','seller_contact'=>'Fiktive Rechnungsstelle','buyer_name'=>'Synthetic Customer','buyer_street'=>'Testweg 2','buyer_postcode'=>'23456','buyer_city'=>'Musterstadt','buyer_email'=>'customer@example.invalid','buyer_reference'=>'SYN-1','description'=>'Synthetic room use','note'=>'Synthetic test only','vat_reason'=>in_array('0',array_column($positions,'tax_rate'),true)?'Steuerbefreiung nach § 19 UStG.':'','document_date'=>$year.'-01-01','delivery_date'=>$year.'-01-01','due_date'=>$year.'-01-10','category'=>'rooms','contact_id'=>'','payment_account'=>$bank,'positions'=>$positions];
 $id=$s->save('',0,$data,requestKey());$s->review($id,1);$entry=$s->issue($id,2);return [$db,$f,$s,$bank,$id,$entry];
