function account(Finance $f,string $entry,array $keys):void{
 $rows=[];foreach($f->positions('entry',$entry) as $i=>$p)$rows[]=['description'=>$p['description'],'amount'=>OutgoingInvoices::amount((int)$p['gross_cents']),'tax_rate'=>(string)$p['tax_rate'],'sphere'=>$p['sphere'],'account'=>$p['account_code'],'booking_key'=>$keys[$i],'input_tax'=>'unknown'];
 $f->updatePositions('entry',$entry,(int)$f->entry($entry)['version'],$rows,'Synthetic explicit domestic output-VAT review');
}
