 $snapshot=$db->query('SELECT payload FROM outgoing_invoices ORDER BY id')->fetchAll();$count=(int)$db->query('SELECT COUNT(*) FROM finance_transactions')->fetchColumn();$x->download($o,$full['hash']);$x->download($o,$full['hash']);
 check($snapshot===$db->query('SELECT payload FROM outgoing_invoices ORDER BY id')->fetchAll()&&$count===(int)$db->query('SELECT COUNT(*) FROM finance_transactions')->fetchColumn()&&(new Documents($db,'admin'))->file($c['document_id'],1)['sha256']===$docHash,"$year $rate% repeated export leaves original PDF, invoices and payments unchanged");
